"""Filesystem searches and edits used by the interactive application.

These are intentionally separate from terminal rendering: a search result is
an immutable view of a file at search time, while edits affect the current file.
"""
import fnmatch
import os
import re
from dataclasses import dataclass, field

SEARCH_MODES = ['Simple', 'Match Case', 'Match Whole Word',
                'Match Case Whole Word', 'Regex']
REPLACE_MODES = ['Simple', 'Preserve Case', 'Delete Line']


def search_expression(text, mode, replacing=False):
    if not text:
        return None
    expression = text if mode == 4 and not replacing else re.escape(text)
    if mode in (2, 3):
        expression = r'\b' + expression + r'\b'
    flags = 0 if mode in (1, 3) or (mode == 4 and not replacing) else re.IGNORECASE
    try:
        # Python and the supported search syntax share the common constructs.
        expression = re.sub(r'\(\?<([A-Za-z_][A-Za-z_0-9]*)>', r'(?P<\1>', expression)
        if not replacing and mode == 4:
            # The observed regular expression interface doesn't support
            # backreferences or look-around assertions.
            if re.search(r'\(\?[=!]|\(\?<[=!]|(?<!\\)\\[1-9]', expression):
                return None
        return re.compile(expression, flags)
    except (re.error, ValueError, OverflowError):
        return None


def preserve_case(replacement, original):
    if original and original.upper() == original:
        return replacement.upper()
    if original and original[0].isupper():
        return replacement[:1].upper() + replacement[1:].lower()
    return replacement.lower()


def line_parts(text):
    """Split on LF, without inventing a last empty line for a trailing LF."""
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    return [line[:-1] if line.endswith('\r') else line for line in lines]


@dataclass
class Snippet:
    line: int
    text: str
    spans: list
    before: list = field(default_factory=list)
    after: list = field(default_factory=list)


@dataclass
class Result:
    path: str
    name: str
    snippets: list
    count: int

    def clone(self):
        return Result(self.path, self.name, list(self.snippets), self.count)


def read_ignore(path):
    try:
        with open(path, encoding='utf-8') as handle:
            return [s.rstrip('\n\r') for s in handle
                    if s.strip() and not s.startswith('#')]
    except (OSError, UnicodeError):
        return []


def ignore_match(rel, directory, rules):
    ignored = False
    rel = rel.replace(os.sep, '/')
    for base, pattern in rules:
        invert = pattern.startswith('!')
        if invert:
            pattern = pattern[1:]
        pattern = pattern.rstrip(' ')
        if not pattern:
            continue
        sub = rel
        if base:
            if not rel.startswith(base + '/'):
                continue
            sub = rel[len(base) + 1:]
        dir_only = pattern.endswith('/')
        pattern = pattern.rstrip('/')
        rooted = pattern.startswith('/')
        pattern = pattern.lstrip('/')
        if '/' in pattern or rooted:
            matched = fnmatch.fnmatchcase(sub, pattern)
            if dir_only and not directory:
                matched = False
        else:
            matched = fnmatch.fnmatchcase(sub.rsplit('/', 1)[-1], pattern)
            if dir_only and not directory:
                matched = False
        if matched:
            ignored = not invert
    return ignored


def collect_files(root):
    root = os.path.abspath(root or '.')
    if os.path.isfile(root):
        return [root]
    if not os.path.isdir(root):
        return []
    git_root = None
    parent = root
    while True:
        if os.path.exists(os.path.join(parent, '.git')):
            git_root = parent
            break
        grandparent = os.path.dirname(parent)
        if grandparent == parent:
            break
        parent = grandparent
    initial = []
    # Git exclusions above the requested root still apply.
    if git_root:
        ancestors = []
        current = root
        while current != git_root:
            current = os.path.dirname(current)
            ancestors.append(current)
        for ancestor in reversed(ancestors):
            for pattern in read_ignore(os.path.join(ancestor, '.gitignore')):
                initial.append(('', pattern))
        for pattern in read_ignore(os.path.join(git_root, '.git', 'info', 'exclude')):
            initial.append(('', pattern))
    found = []

    def walk(directory, relbase, rules):
        rules = list(rules)
        for filename in ('.ignore', '.gitignore'):
            if filename == '.gitignore' and not git_root:
                continue
            rules.extend((relbase, p) for p in read_ignore(os.path.join(directory, filename)))
        try:
            entries = list(os.scandir(directory))
        except OSError:
            return
        files, folders = [], []
        for entry in entries:
            if entry.name.startswith('.') or entry.is_symlink():
                continue
            try:
                is_dir = entry.is_dir(follow_symlinks=False)
                rel = (relbase + '/' if relbase else '') + entry.name
                if ignore_match(rel, is_dir, rules):
                    continue
                if is_dir:
                    folders.append((entry.path, rel))
                elif entry.is_file(follow_symlinks=False):
                    files.append(entry.path)
            except OSError:
                continue
        # Directory traversal returns files first, then subdirectories.
        found.extend(reversed(files))
        for path, rel in folders:
            walk(path, rel, rules)
    walk(root, '', initial)
    return found


def search_files(root, paths, text, mode):
    regex = search_expression(text, mode)
    if regex is None:
        return []
    results = []
    base = os.path.abspath(root or '.')
    for path in paths:
        try:
            with open(path, 'rb') as handle:
                raw = handle.read()
            if b'\0' in raw:
                continue
            content = raw.decode('utf-8')
        except (OSError, UnicodeError):
            continue
        lines = line_parts(content)
        matches = []
        for index, line in enumerate(lines):
            spans = [(m.start(), m.end()) for m in regex.finditer(line)]
            if spans:
                matches.append((index, spans))
        if not matches:
            continue
        snippets = []
        for n, (index, spans) in enumerate(matches):
            previous = matches[n - 1][0] if n else 0
            next_line = matches[n + 1][0] if n + 1 < len(matches) else len(lines)
            start = max(0, index - 3, previous)
            end = min(len(lines), index + 4, next_line)
            snippets.append(Snippet(index, lines[index], spans,
                                    [(j, lines[j]) for j in range(start, index)],
                                    [(j, lines[j]) for j in range(index + 1, end)]))
        name = os.path.relpath(path, base)
        if name == '.':
            name = ''
        results.append(Result(path, name, snippets, sum(len(m[1]) for m in matches)))
    return results


def replace_file(path, query, replacement, search_mode, replace_mode, only_line=None):
    regex = search_expression(query, search_mode, replacing=True)
    if regex is None:
        return
    with open(path, 'rb') as handle:
        text = handle.read().decode('utf-8')
    if replace_mode == 2:
        lines = line_parts(text)
        if only_line is not None:
            lines = [line for index, line in enumerate(lines) if index != only_line]
        else:
            lines = [line for line in lines if regex.search(line) is None]
        changed = '\n'.join(lines)
    else:
        def transform(match):
            if replace_mode == 1:
                return preserve_case(replacement, match.group())
            return replacement
        if only_line is None:
            changed = regex.sub(transform, text)
        else:
            lines = text.splitlines(keepends=True)
            if 0 <= only_line < len(lines):
                lines[only_line] = regex.sub(transform, lines[only_line])
            changed = ''.join(lines)
    with open(path, 'wb') as handle:
        handle.write(changed.encode('utf-8'))
