"""Small UTF-8 terminal renderer and input decoder, without external packages."""
import os
import select
import signal
import sys
import termios
import time
import tty
import unicodedata


def char_width(char):
    if not char or unicodedata.combining(char):
        return 0
    if ord(char) < 32 or 0x7f <= ord(char) < 0xa0:
        return 0
    if unicodedata.east_asian_width(char) in ('W', 'F'):
        return 2
    return 1


def width(text):
    return sum(char_width(ch) for ch in text)


# Styles are (foreground, background, bold, crossed-out).
DEFAULT = (-1, -1, False, False)
WHITE = (15, -1, False, False)
BLUE = (4, -1, False, False)
GRAY = (8, -1, False, False)
GREEN = (2, -1, False, False)
YELLOW = (3, -1, False, False)


def style(fg=-1, bg=-1, bold=False, strike=False):
    return (fg, bg, bold, strike)


class Screen:
    def __init__(self, cols, rows):
        self.w, self.h = cols, rows
        self.cells = [[(' ', DEFAULT) for _ in range(cols)] for _ in range(rows)]
        self.cursor = None

    def fill(self, x, y, w, h, appearance=DEFAULT, char=' '):
        for row in range(max(y, 0), min(y + h, self.h)):
            for col in range(max(x, 0), min(x + w, self.w)):
                self.cells[row][col] = (char, appearance)

    def put(self, x, y, text, appearance=DEFAULT, limit=None):
        if y < 0 or y >= self.h:
            return x
        end = self.w if limit is None else min(self.w, x + max(limit, 0))
        col = x
        for ch in text:
            cw = char_width(ch)
            if cw == 0:
                if unicodedata.combining(ch) and 0 < col <= self.w:
                    old, oldstyle = self.cells[y][col - 1]
                    self.cells[y][col - 1] = (old + ch, oldstyle)
                continue
            if col + cw > end:
                break
            if col >= 0:
                self.cells[y][col] = (ch, appearance)
                if cw == 2:
                    self.cells[y][col + 1] = ('', appearance)
            col += cw
        return col

    def border(self, x, y, w, h, title='', appearance=DEFAULT,
               right_title='', centered=False, content_style=None):
        if w <= 0 or h <= 0:
            return
        if content_style is not None:
            self.fill(x, y, w, h, content_style)
        self.put(x, y, '─' * w, appearance, w)
        if h > 1:
            self.put(x, y + h - 1, '─' * w, appearance, w)
        for row in range(y + 1, y + h - 1):
            self.put(x, row, '│', appearance)
            if w > 1:
                self.put(x + w - 1, row, '│', appearance)
        self.put(x, y, '╭', appearance)
        if w > 1:
            self.put(x + w - 1, y, '╮', appearance)
        if h > 1:
            self.put(x, y + h - 1, '╰', appearance)
            if w > 1:
                self.put(x + w - 1, y + h - 1, '╯', appearance)
        if right_title:
            start = max(x + 1, x + w - 1 - width(right_title))
            if width(right_title) > w - 2:
                right_title = right_title[:max(0, w - 2)]
            self.put(start, y, right_title, appearance, max(0, w - 2))
        if title:
            start = x + 1
            if centered:
                start = x + (w - width(title)) // 2
            self.put(start, y, title, appearance, max(0, x + w - 1 - start))

    def ansi(self, previous=None):
        out = ['\x1b[?25l']
        current_style = None
        for y, row in enumerate(self.cells):
            if previous is not None and y < previous.h and self.w == previous.w and row == previous.cells[y]:
                continue
            out.append(f'\x1b[{y + 1};1H')
            for ch, appearance in row:
                if not ch:
                    continue
                if appearance != current_style:
                    fg, bg, bold, strike = appearance
                    codes = ['0']
                    if bold:
                        codes.append('1')
                    if strike:
                        codes.append('9')
                    if fg >= 0:
                        codes.append(f'38;5;{fg}')
                    if bg >= 0:
                        codes.append(f'48;5;{bg}')
                    out.append('\x1b[' + ';'.join(codes) + 'm')
                    current_style = appearance
                out.append(ch)
        out.append('\x1b[0m')
        if self.cursor is not None:
            x, y = self.cursor
            out.append(f'\x1b[{y + 1};{x + 1}H\x1b[?25h')
        return ''.join(out).encode('utf-8')


class Terminal:
    def __init__(self):
        self.original = None
        self.pending = b''
        self.escape_time = None
        self.resized = True
        self.oldscreen = None

    def enter(self):
        self.original = termios.tcgetattr(sys.stdin.fileno())
        tty.setraw(sys.stdin.fileno())
        os.write(sys.stdout.fileno(), b'\x1b[?1049h\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1006h\x1b[?2004h\x1b[?25l\x1b[2J')
        signal.signal(signal.SIGWINCH, self.resize)

    def resize(self, *unused):
        self.resized = True
        self.oldscreen = None

    def leave(self):
        try:
            os.write(sys.stdout.fileno(), b'\x1b[0m\x1b[?2004l\x1b[?1006l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?1049l\x1b[?25h')
        finally:
            if self.original is not None:
                termios.tcsetattr(sys.stdin.fileno(), termios.TCSADRAIN, self.original)
                self.original = None

    def suspend(self):
        self.leave()
        os.kill(os.getpid(), signal.SIGTSTP)
        self.enter()
        self.oldscreen = None

    def size(self):
        try:
            result = os.get_terminal_size(sys.stdout.fileno())
            return max(1, result.columns), max(1, result.lines)
        except OSError:
            return 80, 24

    def draw(self, screen):
        os.write(sys.stdout.fileno(), screen.ansi(self.oldscreen))
        self.oldscreen = screen
        self.resized = False

    def read(self, timeout=.05):
        if select.select([sys.stdin.fileno()], [], [], timeout)[0]:
            data = os.read(sys.stdin.fileno(), 65536)
            if not data:
                return [('EOF', '')]
            self.pending += data
        events = []
        while self.pending:
            data = self.pending
            if data.startswith(b'\x1b[200~'):
                stop = data.find(b'\x1b[201~')
                if stop < 0:
                    break
                events.append(('PASTE', data[6:stop].decode('utf-8', 'replace')))
                self.pending = data[stop + 6:]
                continue
            if data[0] == 27:
                if len(data) == 1:
                    if self.escape_time is None:
                        self.escape_time = time.monotonic()
                        break
                    if time.monotonic() - self.escape_time < .035:
                        break
                    self.pending = b''
                    self.escape_time = None
                    events.append(('Escape', ''))
                    continue
                self.escape_time = None
                if data[1] in (ord('['), ord('O')):
                    end = 2
                    while end < len(data) and not 0x40 <= data[end] <= 0x7e:
                        end += 1
                    if end >= len(data):
                        break
                    sequence = data[2:end + 1].decode('ascii', 'ignore')
                    self.pending = data[end + 1:]
                    mapping = {'A':'Up', 'B':'Down', 'C':'Right', 'D':'Left',
                               'H':'Home', 'F':'End', 'Z':'Backtab',
                               '1~':'Home', '2~':'Insert', '3~':'Delete',
                               '4~':'End', '5~':'PageUp', '6~':'PageDown',
                               '7~':'Home', '8~':'End',
                               'P':'F1', 'Q':'F2', 'R':'F3', 'S':'F4'}
                    if sequence in mapping:
                        events.append((mapping[sequence], ''))
                    elif ';' in sequence and sequence[-1:] in 'ABCDHF':
                        modifier = sequence[:-1].split(';')[-1]
                        prefix = {'2':'Shift-', '3':'Alt-', '5':'Ctrl-', '6':'Ctrl-Shift-'}.get(modifier, '')
                        events.append((prefix + mapping[sequence[-1]], ''))
                    elif sequence.startswith('<') and sequence[-1:] in ('M','m'):
                        try:
                            btn, x, y = map(int, sequence[1:-1].split(';'))
                            if btn == 64:
                                events.append(('ScrollUp', ''))
                            elif btn == 65:
                                events.append(('ScrollDown', ''))
                        except ValueError:
                            pass
                    continue
                if data[1] < 128:
                    value = chr(data[1])
                    self.pending = data[2:]
                    events.append(('Alt-' + value, ''))
                    continue
                self.pending = data[1:]
                events.append(('Escape', ''))
                continue
            byte = data[0]
            if byte < 32 or byte == 127:
                self.pending = data[1:]
                name = {0:'Ctrl-space', 9:'Tab', 13:'Enter', 27:'Escape', 127:'Backspace'}.get(byte)
                if name is None:
                    name = 'Ctrl-' + chr(byte + 96)
                events.append((name, ''))
                continue
            length = 1 if byte < 128 else (2 if byte < 224 else 3 if byte < 240 else 4)
            if len(data) < length:
                break
            value = data[:length].decode('utf-8', 'replace')
            self.pending = data[length:]
            events.append(('CHAR', value))
        return events
PY"}

