def collect_files(root):
    root = os.path.abspath(root or '.')
    if os.path.isfile(root):
        return [root]
    if not os.path.isdir(root):
        return []
    git_root = None
    parent = root
    while True:
        if os.path.exists(os.path.join(parent, '.git')):
            git_root = parent
            break
        grandparent = os.path.dirname(parent)
        if grandparent == parent:
            break
        parent = grandparent
    initial = []
    # Git exclusions above the requested root still apply.
    if git_root:
        ancestors = []
        current = root
        while current != git_root:
            current = os.path.dirname(current)
            ancestors.append(current)
        for ancestor in reversed(ancestors):
            for pattern in read_ignore(os.path.join(ancestor, '.gitignore')):
                initial.append(('', pattern))
        for pattern in read_ignore(os.path.join(git_root, '.git', 'info', 'exclude')):
            initial.append(('', pattern))
    found = []

    def walk(directory, relbase, rules):
        rules = list(rules)
        for filename in ('.ignore', '.gitignore'):
            if filename == '.gitignore' and not git_root:
                continue
            rules.extend((relbase, p) for p in read_ignore(os.path.join(directory, filename)))
        try:
            entries = list(os.scandir(directory))
        except OSError:
            return
        files, folders = [], []
        for entry in entries:
            if entry.name.startswith('.') or entry.is_symlink():
                continue
            try:
                is_dir = entry.is_dir(follow_symlinks=False)
                rel = (relbase + '/' if relbase else '') + entry.name
                if ignore_match(rel, is_dir, rules):
                    continue
                if is_dir:
                    folders.append((entry.path, rel))
                elif entry.is_file(follow_symlinks=False):
                    files.append(entry.path)
            except OSError:
                continue
        # Directory traversal returns files first, then subdirectories.
        found.extend(reversed(files))
        for path, rel in folders:
            walk(path, rel, rules)
    walk(root, '', initial)
    return found


def search_files(root, paths, text, mode):
    regex = search_expression(text, mode)
    if regex is None:
        return []
    results = []
    base = os.path.abspath(root or '.')
    for path in paths:
        try:
            with open(path, 'rb') as handle:
                raw = handle.read()
            if b'\0' in raw:
                continue
            content = raw.decode('utf-8')
        except (OSError, UnicodeError):
            continue
        lines = line_parts(content)
        matches = []
        for index, line in enumerate(lines):
            spans = [(m.start(), m.end()) for m in regex.finditer(line)]
            if spans:
                matches.append((index, spans))
        if not matches:
            continue
        snippets = []
        for n, (index, spans) in enumerate(matches):
            previous = matches[n - 1][0] if n else 0
            next_line = matches[n + 1][0] if n + 1 < len(matches) else len(lines)
            start = max(0, index - 3, previous)
            end = min(len(lines), index + 4, next_line)
            snippets.append(Snippet(index, lines[index], spans,
                                    [(j, lines[j]) for j in range(start, index)],
                                    [(j, lines[j]) for j in range(index + 1, end)]))
        name = os.path.relpath(path, base)
        if name == '.':
            name = ''
        results.append(Result(path, name, snippets, sum(len(m[1]) for m in matches)))
    return results


def replace_file(path, query, replacement, search_mode, replace_mode, only_line=None):
    regex = search_expression(query, search_mode, replacing=True)
    if regex is None:
        return
    with open(path, 'rb') as handle:
        text = handle.read().decode('utf-8')
    if replace_mode == 2:
        lines = line_parts(text)
        if only_line is not None:
            lines = [line for index, line in enumerate(lines) if index != only_line]
        else:
            lines = [line for line in lines if regex.search(line) is None]
        changed = '\n'.join(lines)
    else:
        def transform(match):
            if replace_mode == 1:
                return preserve_case(replacement, match.group())
            return replacement
        if only_line is None:
            changed = regex.sub(transform, text)
        else:
            lines = text.splitlines(keepends=True)
            if 0 <= only_line < len(lines):
                lines[only_line] = regex.sub(transform, lines[only_line])
            changed = ''.join(lines)
    with open(path, 'wb') as handle:
        handle.write(changed.encode('utf-8'))
