"""Interactive search and replace application.

The terminal UI and its key-driven state machine are implemented here using
only the standard library.  No external search utility is invoked.
"""
import difflib
import json
import os
import re
import signal
import sys
import textwrap
import time

from model import (SEARCH_MODES, REPLACE_MODES, collect_files, search_files,
                   replace_file, preserve_case)
from terminal import (Screen, Terminal, style, width, char_width, DEFAULT,
                      WHITE, BLUE, GRAY, GREEN, YELLOW)

HELP = '''A simple terminal UI for search and replace, ala VS Code

Usage: executable [OPTIONS]

Options:
  -p, --project-root <PATH>  Path to the project root [default: .]
  -h, --help                 Print help
  -V, --version              Print version
'''


def config_directory():
    if os.environ.get('SERPL_CONFIG'):
        return os.environ['SERPL_CONFIG']
    return os.path.join(os.environ.get('XDG_CONFIG_HOME') or
                        os.path.join(os.path.expanduser('~'), '.config'), 'serpl')


def version():
    return ('serpl 0.3.4- (2026-06-11)\n\n'
            'Authors: Yassine Bridi <ybridi@gmail.com>\n\n'
            f'Config directory: {config_directory()}\n')


def argument_error(message, usage=True, extra=''):
    output = 'error: ' + message + '\n'
    if extra:
        output += extra
    if usage:
        output += '\nUsage: executable [OPTIONS]\n'
    output += "\nFor more information, try '--help'.\n"
    sys.stderr.write(output)
    return None, 2


def arguments(args):
    root, used, end = '.', False, False
    index = 0
    while index < len(args):
        item = args[index]
        index += 1
        if not end and item in ('-h', '--help'):
            sys.stdout.write(HELP)
            return None, 0
        if not end and item in ('-V', '--version'):
            sys.stdout.write(version())
            return None, 0
        if not end and item == '--':
            end = True
            continue
        if not end and (item in ('-p', '--project-root') or item.startswith('--project-root=') or
                        (item.startswith('-p') and not item.startswith('--'))):
            if used:
                return argument_error("the argument '--project-root <PATH>' cannot be used multiple times")
            used = True
            if item in ('-p', '--project-root'):
                if index >= len(args) or (args[index].startswith('-') and args[index] != '-'):
                    return argument_error("a value is required for '--project-root <PATH>' but none was supplied", False)
                root = args[index]
                index += 1
            elif item.startswith('--'):
                root = item.split('=', 1)[1]
            else:
                root = item[2:]
                if root.startswith('='):
                    root = root[1:]
            if root == '':
                return argument_error("a value is required for '--project-root <PATH>' but none was supplied", False)
            continue
        if not end and item.startswith(('--help=', '--version=')):
            flag, value = item.split('=', 1)
            return argument_error(f"unexpected value '{value}' for '{flag}' found; no more were expected", False,
                                  f"\nUsage: executable {flag}\n")
        if not end and item.startswith('-') and not item.startswith('--') and len(item) > 2:
            # Short flags may be combined.  Help/version terminate parsing as
            # soon as their letter is encountered.
            for letter in item[1:]:
                if letter == 'h':
                    sys.stdout.write(HELP)
                    return None, 0
                if letter == 'V':
                    sys.stdout.write(version())
                    return None, 0
                return argument_error(f"unexpected argument '-{letter}' found")
        value = item.split('=', 1)[0] if item.startswith('--') else item
        extra = ''
        if not end and item.startswith('--'):
            suggestion = difflib.get_close_matches(value, ['--project-root', '--help', '--version'], n=1, cutoff=.76)
            if suggestion:
                extra = f"\n  tip: a similar argument exists: '{suggestion[0]}'\n"
        return argument_error(f"unexpected argument '{value}' found", extra=extra)
    return root, None


FOOTERS = {
    0: 'Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>',
    1: 'Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>',
    2: 'Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k>',
    3: 'Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k>',
    'help': 'Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>',
    'confirm': 'Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>',
}
GLOBAL_HELP = [
    ' - Ctrl-c: Quit',
    ' - Ctrl-d: Quit',
    ' - Ctrl-b: Help dialog',
    ' - Ctrl-o: Process Replace For All Files',
    ' - Ctrl-n: Loop through search and replace modes',
    ' - Enter: Select/Deselect file',
    ' - d: delete file/delete line from the replace process',
    ' - r: Replace Selected File Or Line',
]
NAV_HELP = [
    ' - Tab: Loop through panes',
    ' - j/UpArrow: Move up',
    ' - k/DownArrow: Move down',
    ' - h/g/LeftArrow: Move to Top',
    ' - l/G/RightArrow: Move to Bottom',
]


class Input:
    def __init__(self):
        self.value = ''
        self.cursor = 0
        self.scroll = 0

    def insert(self, value):
        self.value = self.value[:self.cursor] + value + self.value[self.cursor:]
        self.cursor += len(value)

    def previous_word(self):
        index = self.cursor
        while index and self.value[index - 1].isspace():
            index -= 1
        while index and not self.value[index - 1].isspace():
            index -= 1
        return index

    def next_word(self):
        index = self.cursor
        while index < len(self.value) and self.value[index].isspace():
            index += 1
        while index < len(self.value) and not self.value[index].isspace():
            index += 1
        return index

    def event(self, key, value):
        if key == 'CHAR':
            self.insert(value)
        elif key == 'PASTE':
            self.insert(value.replace('\r', '').replace('\n', ''))
        elif key in ('Left', 'Ctrl-b'):
            self.cursor = max(0, self.cursor - 1)
        elif key in ('Right', 'Ctrl-f'):
            self.cursor = min(len(self.value), self.cursor + 1)
        elif key in ('Home', 'Ctrl-a'):
            self.cursor = 0
        elif key in ('End', 'Ctrl-e'):
            self.cursor = len(self.value)
        elif key in ('Alt-b', 'Ctrl-Left'):
            self.cursor = self.previous_word()
        elif key in ('Alt-f', 'Ctrl-Right'):
            self.cursor = self.next_word()
        elif key in ('Backspace', 'Ctrl-h') and self.cursor:
            self.value = self.value[:self.cursor - 1] + self.value[self.cursor:]
            self.cursor -= 1
        elif key == 'Delete':
            self.value = self.value[:self.cursor] + self.value[self.cursor + 1:]
        elif key == 'Ctrl-u':
            self.value = self.value[self.cursor:]
            self.cursor = 0
        elif key == 'Ctrl-k':
            self.value = self.value[:self.cursor]
        elif key in ('Ctrl-w', 'Alt-Backspace'):
            previous = self.previous_word()
            self.value = self.value[:previous] + self.value[self.cursor:]
            self.cursor = previous
        elif key == 'Alt-d':
            following = self.next_word()
            self.value = self.value[:self.cursor] + self.value[following:]

    def visible(self, max_width):
        max_width = max(0, max_width)
        position = width(self.value[:self.cursor])
        if position < self.scroll:
            self.scroll = position
        elif position >= self.scroll + max_width:
            self.scroll = max(0, position - max_width)
        consumed, index = 0, 0
        while index < len(self.value) and consumed < self.scroll:
            consumed += char_width(self.value[index])
            index += 1
        return self.value[index:], max(0, position - consumed)


def normalize_config_key(text):
    text = text.strip('<>')
    aliases = {'tab':'Tab', 'backtab':'Backtab', 'esc':'Escape', 'escape':'Escape',
               'enter':'Enter', 'space':' ', 'up':'Up', 'down':'Down',
               'left':'Left', 'right':'Right', 'backspace':'Backspace'}
    if text.lower() in aliases:
        return aliases[text.lower()]
    text = re.sub(r'(?i)^ctrl-', 'Ctrl-', text)
    text = re.sub(r'(?i)^alt-', 'Alt-', text)
    return text


def load_keys():
    keys = {'Ctrl-d':'Quit', 'Ctrl-c':'Quit', 'Ctrl-z':'Suspend',
            'Ctrl-r':'Refresh', 'Tab':'LoopOverTabs', 'Backtab':'BackLoopOverTabs',
            'Ctrl-o':'ProcessReplace', 'Ctrl-b':'ShowHelp'}
    directory = config_directory()
    for suffix in ('json', 'json5', 'toml'):
        path = os.path.join(directory, 'config.' + suffix)
        try:
            with open(path, encoding='utf-8') as handle:
                text = handle.read()
            if suffix == 'toml':
                import tomllib
                config = tomllib.loads(text)
            else:
                if suffix == 'json5':
                    text = re.sub(r'/\*.*?\*/|//[^\n]*', '', text, flags=re.S)
                    text = re.sub(r',\s*([}\]])', r'\1', text)
                    text = re.sub(r'([{,]\s*)([A-Za-z_][\w-]*)(\s*:)', r'\1"\2"\3', text)
                    text = re.sub(r"'([^'\\]*(?:\\.[^'\\]*)*)'", lambda m: json.dumps(m[1]), text)
                config = json.loads(text)
            for name, action in config.get('keybindings', {}).items():
                if isinstance(action, str):
                    keys[normalize_config_key(name)] = action
        except (OSError, ValueError, ImportError, TypeError):
            continue
    return keys


class Application:
    def __init__(self, root):
        self.root = root
        self.paths = collect_files(root)
        self.keys = load_keys()
        self.running = True
        self.help_page = 0
        self.notification = None
        self.reset()

    def reset(self):
        self.search = Input()
        self.replace = Input()
        self.search_mode = 0
        self.replace_mode = 0
        self.focus = 0
        self.tab_index = 0
        self.footer = 0
        self.results = []
        self.file_selected = None
        self.file_offset = 0
        self.preview = None
        self.preview_selected = None
        self.preview_offset = 0
        self.modal = None
        self.saved_focus = 0
        self.saved_footer = 0
        self.confirm_selected = 1

    def search_now(self):
        self.results = search_files(self.root, self.paths, self.search.value, self.search_mode)
        if self.file_selected is not None:
            self.file_selected = min(self.file_selected, len(self.results) - 1) if self.results else None
        self.file_offset = 0

    def load_preview(self, fallback=False):
        index = self.file_selected
        if index is None and fallback:
            index = 0
        if index is not None and 0 <= index < len(self.results):
            self.preview = self.results[index].clone()
            self.preview_offset = 0
            self.clamp_preview()

    def set_focus(self, focus):
        self.focus = focus
        if focus in (0, 1, 2):
            self.tab_index = focus
        self.footer = focus

    def show_help(self):
        if self.modal == 'help':
            return
        self.saved_focus = self.focus
        self.saved_footer = self.footer
        self.saved_modal = self.modal
        self.modal = 'help'
        self.focus = None
        self.footer = 'help'

    def close_help(self):
        self.modal = self.saved_modal
        self.focus = self.saved_focus
        self.footer = self.saved_footer

    def show_confirm(self):
        self.modal = 'confirm'
        self.focus = None
        self.footer = 'confirm'
        self.confirm_selected = 1

    def notify(self, message):
        self.notification = (message, time.monotonic() + 3)

    def process_all(self):
        try:
            for result in self.results:
                replace_file(result.path, self.search.value, self.replace.value,
                             self.search_mode, self.replace_mode)
            self.reset()
            self.notify('Search and replace completed successfully')
        except (OSError, UnicodeError, ValueError):
            self.modal = None
            self.notify('Search and replace failed')

    def move_file(self, direction):
        if not self.results:
            return
        size = len(self.results)
        if direction == 'first':
            self.file_selected = 0
        elif direction == 'last':
            self.file_selected = size - 1
        elif self.file_selected is None:
            self.file_selected = 0 if direction == 'next' else size - 1
        else:
            self.file_selected = (self.file_selected + (1 if direction == 'next' else -1)) % size
        self.load_preview()

    def remove_file(self, replace=False):
        if self.file_selected is None or not self.results:
            return
        index = min(self.file_selected, len(self.results) - 1)
        result = self.results[index]
        if replace:
            try:
                replace_file(result.path, self.search.value, self.replace.value,
                             self.search_mode, self.replace_mode)
            except (OSError, UnicodeError, ValueError):
                return
        self.results.pop(index)
        self.file_selected = min(index, len(self.results) - 1) if self.results else None
        self.load_preview()

    def preview_rows(self):
        if self.preview is None:
            return []
        rows = []
        for snippet in self.preview.snippets:
            rows.extend(('context', index, text, None) for index, text in snippet.before)
            rows.append(('match', snippet.line, snippet.text, snippet))
            rows.extend(('context', index, text, None) for index, text in snippet.after)
            rows.append(('separator', 0, '', None))
        return rows

    def clamp_preview(self):
        rows = self.preview_rows()
        if self.preview_selected is not None:
            self.preview_selected = min(self.preview_selected, len(rows) - 1) if rows else None
        self.preview_offset = min(self.preview_offset, max(0, len(rows) - 1))

    def move_preview(self, direction):
        choices = [i for i, row in enumerate(self.preview_rows()) if row[0] == 'match']
        if not choices:
            return
        if direction == 'first':
            self.preview_selected = choices[0]
        elif direction == 'last':
            self.preview_selected = choices[-1]
        elif direction == 'next':
            self.preview_selected = next((i for i in choices if self.preview_selected is None or i > self.preview_selected), choices[0])
        else:
            self.preview_selected = next((i for i in reversed(choices) if self.preview_selected is None or i < self.preview_selected), choices[-1])

    def remove_line(self, replace=False):
        rows = self.preview_rows()
        if self.preview_selected is None or self.preview_selected >= len(rows):
            return
        kind, index, text, snippet = rows[self.preview_selected]
        if kind != 'match' or self.preview is None:
            return
        if replace:
            try:
                replace_file(self.preview.path, self.search.value, self.replace.value,
                             self.search_mode, self.replace_mode, only_line=index)
            except (OSError, UnicodeError, ValueError):
                return
        self.preview.snippets = [s for s in self.preview.snippets if s is not snippet]
        self.preview.count -= 1
        for result in self.results:
            if result.path == self.preview.path:
                result.snippets = [s for s in result.snippets if s is not snippet]
                result.count -= 1
                break
        self.clamp_preview()

    def global_action(self, action, terminal):
        if action == 'Quit':
            self.running = False
        elif action == 'Suspend':
            terminal.suspend()
        elif action == 'Refresh':
            self.paths = collect_files(self.root)
        elif action == 'ShowHelp':
            self.show_help()
        elif action == 'ProcessReplace':
            self.show_confirm()
        elif action in ('LoopOverTabs', 'BackLoopOverTabs'):
            if self.modal is None and self.focus != 3:
                self.set_focus((self.tab_index + (1 if action == 'LoopOverTabs' else -1)) % 3)

    def event(self, key, value, terminal):
        if key == 'EOF':
            self.running = False
            return
        lookup = value if key == 'CHAR' else key
        action = self.keys.get(lookup)
        if action:
            # Refresh is also a character-r input to the result panes.
            self.global_action(action, terminal)
            if action != 'Refresh':
                return
        char = value if key == 'CHAR' else key[-1] if key.startswith(('Ctrl-', 'Alt-')) and len(key.rsplit('-', 1)[-1]) == 1 else ''
        if self.modal == 'help':
            if key == 'Escape' or char == 'q':
                self.close_help()
            elif key == 'Right':
                self.help_page = (self.help_page + 1) % 2
            elif key == 'Left':
                self.help_page = (self.help_page - 1) % 2
            elif char in ('1', '2'):
                self.help_page = int(char) - 1
            return
        if self.modal == 'confirm':
            if key == 'Escape':
                self.modal = None
            elif key == 'Enter':
                if self.confirm_selected == 0:
                    self.process_all()
                else:
                    self.modal = None
            elif key == 'Left' or char == 'h':
                self.confirm_selected = 0
            elif key == 'Right' or char == 'l':
                self.confirm_selected = 1
            return
        if self.focus in (0, 1):
            if key == 'Ctrl-n':
                if self.focus == 0:
                    self.search_mode = (self.search_mode + 1) % len(SEARCH_MODES)
                    self.load_preview(fallback=True)
                    self.search_now()
                else:
                    self.replace_mode = (self.replace_mode + 1) % len(REPLACE_MODES)
                return
            if key == 'Enter':
                if self.focus == 0:
                    self.search_now()
                return
            if self.focus == 0:
                self.search.event(key, value)
            elif self.replace_mode != 2:
                self.replace.event(key, value)
            return
        if self.focus not in (2, 3):
            return
        if key == 'Enter':
            self.set_focus(3 if self.focus == 2 else 2)
            return
        direction = None
        if key == 'Down' or char == 'j':
            direction = 'next'
        elif key == 'Up' or char == 'k':
            direction = 'previous'
        elif key in ('Left', 'Backspace') or char in ('h', 'g'):
            direction = 'first'
        elif key == 'Right' or char in ('l', 'G'):
            direction = 'last'
        if direction:
            if self.focus == 2:
                self.move_file(direction)
            else:
                self.move_preview(direction)
        elif char in ('d', 'r'):
            if self.focus == 2:
                self.remove_file(replace=(char == 'r'))
            else:
                self.remove_line(replace=(char == 'r'))

    def draw_input(self, screen, field, x, y, w, title, mode, active, placeholder=False):
        border = style(2, bold=True) if active else WHITE
        screen.border(x, y, w, 3, title, border, '[' + mode + ']', content_style=WHITE)
        value, pos = field.visible(max(0, w - 3))
        if placeholder:
            value = '[Entire line will be deleted]'
        screen.put(x + 1, y + 1, value, GRAY if placeholder else WHITE, max(0, w - 2))
        if active:
            screen.cursor = (min(screen.w - 1, x + 1 + min(pos, max(0, w - 3))), min(screen.h - 1, y + 1))

    def draw_results(self, screen, left, height):
        y, h = 6, max(0, height - 6)
        appearance = style(2, bold=True) if self.focus == 2 else WHITE
        screen.border(0, y, left, h, 'Result List', appearance, content_style=WHITE)
        inner_h = max(0, h - 2)
        if self.file_selected is not None:
            if self.file_selected < self.file_offset:
                self.file_offset = self.file_selected
            elif self.file_selected >= self.file_offset + inner_h:
                self.file_offset = self.file_selected - inner_h + 1
        self.file_offset = max(0, self.file_offset)
        for slot, index in enumerate(range(self.file_offset, min(len(self.results), self.file_offset + inner_h))):
            result = self.results[index]
            row = y + 1 + slot
            selected = index == self.file_selected
            bg = 4 if selected else -1
            screen.fill(1, row, max(0, left - 2), 1, style(15, bg))
            end = left - 1
            col = screen.put(1, row, result.name + ' (', style(15, bg), max(0, end - 1))
            col = screen.put(col, row, str(result.count), style(3, bg), max(0, end - col))
            screen.put(col, row, ')', style(15, bg), max(0, end - col))

    def draw_preview(self, screen, left, height):
        w = screen.w - left
        screen.border(left, 0, w, height, 'Preview', GREEN if self.focus == 3 else DEFAULT)
        rows = self.preview_rows()
        available = max(0, height - 2)
        if self.preview_selected is not None:
            if self.preview_selected < self.preview_offset:
                self.preview_offset = self.preview_selected
            elif self.preview_selected >= self.preview_offset + available:
                self.preview_offset = self.preview_selected - available + 1
        self.preview_offset = max(0, self.preview_offset)
        prefix = self.preview_selected is not None
        content_left, end = left + 1, screen.w - 1
        for slot, index in enumerate(range(self.preview_offset, min(len(rows), self.preview_offset + available))):
            kind, number, text, snippet = rows[index]
            y = 1 + slot
            selected = index == self.preview_selected
            base = style(15, bold=True) if selected else DEFAULT
            if selected:
                screen.fill(content_left, y, max(0, end - content_left), 1, base)
            col = content_left
            if prefix:
                col = screen.put(col, y, '> ' if selected else '  ', base, max(0, end - col))
            if kind == 'separator':
                sepstyle = base if selected else (YELLOW if self.focus == 3 else GRAY)
                screen.put(col, y, '-' * max(0, end - col), sepstyle, max(0, end - col))
                continue
            numstyle = base if selected else (style(10) if kind == 'match' else BLUE)
            col = screen.put(col, y, f'{number + 1:4} ', numstyle, max(0, end - col))
            if kind == 'context':
                screen.put(col, y, text, base if selected else GRAY, max(0, end - col))
                continue
            if self.replace_mode == 2:
                screen.put(col, y, text, style(15, 1, selected, True), max(0, end - col))
                continue
            start = 0
            for match_start, match_end in snippet.spans:
                col = screen.put(col, y, text[start:match_start], base, max(0, end - col))
                original = text[match_start:match_end]
                if self.replace.value:
                    col = screen.put(col, y, original, style(15, 9, selected, True), max(0, end - col))
                    replacement = self.replace.value
                    if self.replace_mode == 1:
                        replacement = preserve_case(replacement, original)
                    col = screen.put(col, y, replacement, style(15, 2, selected), max(0, end - col))
                else:
                    col = screen.put(col, y, original, style(15 if selected else -1, 4, selected), max(0, end - col))
                start = match_end
            screen.put(col, y, text[start:], base, max(0, end - col))

    def draw_help(self, screen):
        w, h = min(80, screen.w), min(15, screen.h)
        x, y = max(0, (screen.w - w) // 2), max(0, (screen.h - h) // 2)
        screen.border(x, y, w, h, '', YELLOW, right_title="Press 'q' to close", content_style=WHITE)
        col = screen.put(x + 1, y, ' [1] Global ', GREEN if self.help_page == 0 else YELLOW, max(0, w - 2))
        col = screen.put(col, y, '─', YELLOW, max(0, x + w - 1 - col))
        screen.put(col, y, ' [2] Navigation ', GREEN if self.help_page == 1 else YELLOW, max(0, x + w - 1 - col))
        lines = GLOBAL_HELP if self.help_page == 0 else NAV_HELP
        row = y + 2
        for text in lines:
            for part in textwrap.wrap(text, width=max(1, w - 2), replace_whitespace=False, drop_whitespace=False) or ['']:
                if row < y + h - 1:
                    screen.put(x + 1, row, part, WHITE, max(0, w - 2))
                    row += 1
        screen.cursor = None

    def draw_confirm(self, screen):
        w, h = min(56, screen.w), min(8, screen.h)
        x, y = max(0, (screen.w - w) // 2), max(0, (screen.h - h) // 2)
        screen.border(x, y, w, h, 'Confirm Dialog', YELLOW, centered=True, content_style=WHITE)
        for offset, text in [(2, 'This action will modify the files in this directory.'),
                             (3, 'Are you sure you want to continue?')]:
            screen.put(x + max(1, (w - width(text)) // 2), y + offset, text, WHITE, max(0, w - 2))
        col = x + max(1, (w - 18) // 2)
        for index, label in enumerate((' Continue ', ' Cancel ')):
            active = index == self.confirm_selected
            appearance = style(3, bold=True) if active else WHITE
            screen.put(col, y + 6, label, appearance, max(0, x + w - 1 - col))
            if active:
                screen.put(col, y + h - 1, '─' * len(label), appearance, max(0, x + w - 1 - col))
            col += len(label)
        screen.cursor = None

    def draw_notification(self, screen):
        if self.notification is None:
            return
        text, expiry = self.notification
        if time.monotonic() >= expiry:
            self.notification = None
            return
        w, h = min(width(text) + 4, max(0, screen.w - 2)), 3
        x, y = screen.w - w - 1, screen.h - 5
        if w > 1 and y >= 0:
            screen.fill(x, y, w, h)
            screen.border(x, y, w, h, 'Notification', style(4, bold=True))
            screen.put(x + 1, y + 1, text, BLUE, max(0, w - 2))

    def render(self, cols, rows):
        screen = Screen(cols, rows)
        height = max(0, rows - 1)
        left = int(cols * .30 + .5)
        self.draw_preview(screen, left, height)
        self.draw_input(screen, self.search, 0, 0, left, 'Search', SEARCH_MODES[self.search_mode], self.focus == 0)
        self.draw_input(screen, self.replace, 0, 3, left, 'Replace', REPLACE_MODES[self.replace_mode], self.focus == 1, self.replace_mode == 2)
        self.draw_results(screen, left, height)
        footer = FOOTERS.get(self.footer, FOOTERS[0])
        footer_width = max(1, int(cols * .70 + .5))
        first = textwrap.wrap(footer, width=footer_width, break_long_words=True, break_on_hyphens=False)
        if first:
            screen.put(0, rows - 1, first[0], BLUE, cols)
        if self.modal == 'help':
            self.draw_help(screen)
        elif self.modal == 'confirm':
            self.draw_confirm(screen)
        self.draw_notification(screen)
        return screen

    def run(self, terminal):
        terminal.draw(self.render(*terminal.size()))
        while self.running:
            events = terminal.read(.05)
            redraw = bool(events) or terminal.resized
            for key, value in events:
                self.event(key, value, terminal)
                if not self.running:
                    break
            if self.notification and time.monotonic() >= self.notification[1]:
                self.notification = None
                redraw = True
            if redraw and self.running:
                terminal.draw(self.render(*terminal.size()))


def main():
    root, code = arguments(sys.argv[1:])
    if code is not None:
        return code
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        sys.stderr.write('serpl error: Something went wrong\nError: \n'
                         '   0: \x1b[91mResource temporarily unavailable (os error 11)\x1b[0m\n')
        return 1
    terminal = Terminal()
    try:
        app = Application(root)
        terminal.enter()
        app.run(terminal)
    except KeyboardInterrupt:
        pass
    finally:
        terminal.leave()
    return 0


if __name__ == '__main__':
    sys.exit(main())
